create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.BESCH_BEST_LIEF_LBS cluster by (
     FEHLLIEFERUNG_KZ,
     MANDANT_ID,
     DAT_BEST_BELEG 
)(
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH',
	BEST_BELEG_ID NUMBER(18,0) NOT NULL COMMENT 'Das Feld enthält die Beleg ID der Bestellung und dient der eindeutigen Identifikation der Bestellbelege. Aus ebeln',
	BEST_BELEG_POS_ID NUMBER(38,0) NOT NULL COMMENT 'Die Belegposition ID der Bestellung dient der eindeutigen Identifikation der Bestellpositionen pro Bestellung.Aus ebelp',
	DAT_BUCH DATE NOT NULL COMMENT 'Datum, unter dem der Beleg in der Buchhaltung bzw. in der Kostenrechnung erfasst wird.\n            Aus der Tabelle lagerbew',
	ENDLIEF_FG NUMBER(38,0) NOT NULL COMMENT 'Ist KEIN Flag. Gibt an, ob diese Position abgeschlossen, d. h. ob die dazugehörige Faktura beglichen ist. Aus der Tabelle besch_best_det. -1,wenn Liefermenge < Bestellmenge, =1, wenn  Liefermenge= Bestellmenge, 2, wenn  Liefermenge> Bestellmenge\n            ',
	BEST_MENGE_ORIG_FG NUMBER(38,0) NOT NULL COMMENT 'Kennzeichnet den Satz mit der originalen Bestellmenge, da mehrere Teillieferungen mit Teilmengen vorhanden sein können',
	ANNAHMEVERWEIGERUNG_ID NUMBER(38,0) NOT NULL COMMENT 'Dieses Attribut enthält die Gründe für die Annahmeverweigerung. Referenz zu der Tabelle l_annahmeverweigerung bei Lägern. Bei Märkten enthält die Spalte den Wert -1',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Artikel ID',
	GP_ID NUMBER(38,0) NOT NULL COMMENT 'Geschäftspartner - ID (Lieferanten - ID)',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	BESTELLART_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Durch die Einkaufsbelegart kann man z.B. zwischen einer Bestellung, einer Anfrage und einem Lieferplan unterscheiden.',
	DAT_BEST_BELEG DATE NOT NULL COMMENT 'Dieses Feld enthält das Belegdatum der Bestellung.',
	DAT_LIEF_WUNSCH DATE NOT NULL COMMENT 'Datum, an dem die Ware geliefert bzw. die Dienstleistung erbracht werden soll. Aus lief_einteilung',
	DAT_LIEF_BEWERTUNG DATE COMMENT 'Statistikrelevantes Lieferdatum aus lief_einteilung',
	MENGE_LIEF NUMBER(18,3) NOT NULL COMMENT 'Gibt die gelieferte Menge in Bestellpreismengeneinheit an. Aus lagerbew_det',
	BETRAG_LAGERBEW_EK_N NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Betrag der Belegposition in der Hauswährung des Buchungskreises auf Basis lder Menge aus lagerbew_det. Entspricht dem eknetto.',
	BETRAG_BEST_EK_N NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'redundanter Wert zur Performancesteigerung im frontend, erspart den join zur art_gp_wup_zu_per, Berechnung menge_best_bme*eknetto*komponentenmenge.',
	MENGE_BEST_BME NUMBER(18,3) NOT NULL COMMENT 'bestellte Menge des Artikel dieser Position in Bestellmengeneinheit',
	FEHLLIEFERUNG_KZ NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Zeigt Status der Fehllieferung auf Belegebene, nicht Positionsebene an.0=keine Fehlmenge, -1=Fehlmenge in  einer Pos innerhalb spaet_lief_tage, -2=Fehlmenge in  einer Pos außerhalb spaet_lief_tage,1=mind 1 Position mit Fehlmenge außerh. Lieferlimit, 2=mind. 1 Position mit Fehlmenge innerhalb Lieferlimit',
	MENGE_LIEF_IST_KOLLI NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Liefermenge in Kolli',
	MENGE_LIEF_SOLL_KOLLI NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Bestellmenge in Kolli',
	BETRAG_FEHLMENGE_VK_BRUTTO NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Fehlwert (Bestellmenge - WE-Menge) zum VK brutto der Preiskategorie 1',
	WRG_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' DEFAULT 'EUR' COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	LAGERORT_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'Schlüssel für die Lagerorte. Die Lagerorte sind pro Werk/Betrieb eindeutig. Aus lgort',
	LOESCH_FG_EKKO NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Lösch-Flag bezogen auf den Bestellkopf besch_best',
	LOESCH_FG_EKPO NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Lösch-Flag bezogen auf die Bestellposition besch_best_det',
	SELBSTABHOL_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Das Flag kennzeichnet die Selbstabholung dieser Position, Wert 1 entspricht selbstabgeholt Wird aus Tabelle besch_best_det übernommen',
	ANZAHL_LIEF NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl der Lieferungen mit Bewegungsart 101, 905 aus der Tabelle lagerbew',
	ANZAHL_LIEF_POS NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl der Lieferpositionen mit Bewegungsart 101, 905 aus der Tabelle lagerbew_det',
	LAGER_BEWART_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Schlüssel der Bewegungsarten der Lagerbewegung.',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	VK_NETTO_LIEF_SOLL NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Liefermenge soll bewertet mit dem Verkaufspreis minus MehrWertSteuer. Redundant abgelegt zur Performancesteigerung',
	VK_NETTO_LIEF_IST NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Liefermenge Ist bewertet mit dem Verkaufspreis minus MehrWertSteuer. Redundant abgelegt zur Performancesteigerung',
	ZEIT_ENDLIEF_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag : zeit_endlief',
	constraint PK_BESCH_BEST_LIEF_LBS primary key (MANDANT_ID, BEST_BELEG_ID, BEST_BELEG_POS_ID, DAT_BUCH)
)COMMENT='TP2_AIS - Denormalisierte Tabelle fuer LBS Logistikqualitaet auf Basis besch_best_det. Enthaelt Elemente aus lagerbew_det, besch_best, lief_einteilung'
;
